        async function initializeUI() {
            try {
                const { SAM_data } = await getVariables();//
                populateUI(SAM_data);//
            } catch (error) {
                console.error("加载数据失败:", error);//
                document.getElementById('ui-container').innerHTML = "<p>数据加载失败...</p>";//
            }
