        function formatDateTime(isoString) {
            const date = new Date(isoString);//
            const year = date.getFullYear();//
            const month = (date.getMonth() + 1).toString().padStart(2, '0');//
            const day = date.getDate().toString().padStart(2, '0');//
            const hours = date.getHours().toString().padStart(2, '0');//
            const minutes = date.getMinutes().toString().padStart(2, '0');//
            return `${year}-${month}-${day}, ${hours}:${minutes}`;//
        }

        function createProgressBar(label, value, max) {
            const percentage = (value / max) * 100;//
            const item = document.createElement('div');//
            item.className = 'stat-item';//

            item.innerHTML = `
                <span class="stat-label">${label}</span>
                <div class="progress-bar">
                    <div class="progress-fill" style="width: ${percentage}%;//"></div>
                </div>
                <span class="stat-value">${value} / ${max}</span>
            `;//
            return item;//
        }

        function createTag(text) {
             const tag = document.createElement('span');//
             tag.className = 'tag';//
             tag.textContent = text;//
             return tag;//
        }

        function populateUI(data) {
            // -- 全局时间 --
            document.getElementById('system-time').textContent = `数据刷新于: ${formatDateTime(data.time)}`;//

            // -- 页面1: 游戏进度 --
            const event = data.static.event;//
            document.getElementById('event-time').textContent = formatDateTime(data.time);//
            document.getElementById('event-weekday').textContent = event.weekday;//

            const mc = data.static.mc;//
            document.getElementById('mc-location').textContent = mc.location;//
            document.getElementById('mc-appearance').textContent = mc.appearance;//
            document.getElementById('mc-mission').textContent = mc.mission;//
            document.getElementById('mc-credits').textContent = mc.credits.toLocaleString();//

            const inventoryContainer = document.getElementById('mc-inventory');//
            inventoryContainer.innerHTML = '';//
            mc.inventory.forEach(item => inventoryContainer.appendChild(createTag(item)));//

            const storageList = document.getElementById('ship-storage-list');//
            storageList.innerHTML = '';//
            mc.ship_storage.forEach(item => {
                const li = document.createElement('li');//
                li.innerHTML = `<span class="value highlight">${item.item}</span>: <span class="label">${item.quantity}</span>`;//
                storageList.appendChild(li);//
            });//

            // -- 页面2: 艾琳的状态 --
            const irin = data.static.irin;//
            document.getElementById('irin-location').textContent = irin.location;//
            document.getElementById('irin-body-appearance').textContent = irin.body_appearance;//
            document.getElementById('irin-breast-appearance').textContent = irin.breast_appearance;//
            document.getElementById('irin-vaginal-appearance').textContent = irin.vaginal_appearance;//

            const statsContainer = document.getElementById('irin-stats');//
            statsContainer.innerHTML = '';//
            statsContainer.appendChild(createProgressBar('好感度', irin.affection, 1000));//
            statsContainer.appendChild(createProgressBar('焦虑值', irin.anxiety, 1000));//
            statsContainer.appendChild(createProgressBar('欲望', irin.lust, 1000));//

            const personalityContainer = document.getElementById('irin-personality');//
            personalityContainer.innerHTML = '';//
            irin.personality.forEach(p => {
                personalityContainer.appendChild(createProgressBar(p.trait, p.level, 100));//
            });//

            const fetishesContainer = document.getElementById('irin-fetishes');//
            fetishesContainer.innerHTML = '';//
             irin.fetishes.forEach(f => {
                fetishesContainer.appendChild(createProgressBar(f.name, f.intensity, 100));//
            });//

            const likesContainer = document.getElementById('irin-likes');//
            likesContainer.innerHTML = '';//
            irin.likes.forEach(item => likesContainer.appendChild(createTag(item)));//

            const dislikesContainer = document.getElementById('irin-dislikes');//
            dislikesContainer.innerHTML = '';//
            irin.dislikes.forEach(item => dislikesContainer.appendChild(createTag(item)));//

            const itemsContainer = document.getElementById('irin-important-items');//
            itemsContainer.innerHTML = '';//
            irin.important_items.forEach(item => itemsContainer.appendChild(createTag(item)));//

            // -- 响应摘要 --
            const summaryContent = document.getElementById('response-summary-content');//
            if (data.responseSummary && data.responseSummary.length > 0) {
                 const ul = document.createElement('ul');//
                 data.responseSummary.forEach(item => {
                    const li = document.createElement('li');//
                    li.textContent = item;//
                    ul.appendChild(li);//
                 });//
                 summaryContent.appendChild(ul);//
            } else {
                summaryContent.textContent = '无摘要信息。';//
            }
        }

        function setupTabs() {
            const uiContainer = document.getElementById('ui-container');//
            const tabButtons = document.querySelectorAll('.tab-button');//
            const pages = document.querySelectorAll('.page');//

            tabButtons.forEach(button => {
                button.addEventListener('click', () => {
                    const targetId = button.dataset.target;//

                    // 切换按钮的激活状态
                    tabButtons.forEach(btn => btn.classList.remove('active'));//
                    button.classList.add('active');//

                    // 切换页面的可见性
                    pages.forEach(page => {
                        if (page.id === targetId) {
                            page.classList.add('active');//
                        } else {
                            page.classList.remove('active');//
                        }
                    });//

                    // 切换主题
                    if (targetId === 'irin-status-page') {
                        uiContainer.classList.add('irin-theme');//
                    } else {
                        uiContainer.classList.remove('irin-theme');//
                    }
                });//
            });//
        }

    </script>
</body>
